  readonly object publishSync=new object();readonly ManualUpdateQueue manualUpdates=new ManualUpdateQueue();Thread worker;Core core;RealtimeChangeMonitor realtime;readonly ManualResetEvent stopping=new ManualResetEvent(false);string runId=Guid.NewGuid().ToString("N");long lastProgress,databaseProbeAt;volatile string state="STARTING";DirectoryScanPlan plan;volatile Exception failure;volatile bool stopRequested;volatile bool engineReady,databaseReady,manualControlReady;int scanRequested;int cacheHits;CleanDirectoryCache cache;string generation;
