  void VerifyEngine(){string path=Path.Combine(ProgramRoot,"engine-integrity.json");FolderMonitor.NoLinks(path);EngineFile[] files=Data.Read<EngineFile[]>(path,4194304);if(files==null||files.Length<2||files.Length>4096)throw new IOException("Variklio vientisumo manifestas nepatvirtintas.");string root=Path.Combine(ProgramRoot,"engine");bool scan=false,fresh=false;foreach(var f in files){if(f==null||!Data.Hash(f.Hash)||string.IsNullOrEmpty(f.Name)||Path.IsPathRooted(f.Name)||f.Name.Contains("..")||f.Name.Any(c=>c<' '))throw new IOException("Variklio manifestas sugadintas.");string p=Path.GetFullPath(Path.Combine(root,f.Name));if(!p.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("Variklio failas už ribų.");FolderMonitor.NoLinks(p);using(var input=File.OpenRead(p))using(var sha=SHA256.Create())if(!string.Equals(Data.Hex(sha.ComputeHash(input)),f.Hash,StringComparison.OrdinalIgnoreCase))throw new IOException("Variklio vientisumas nepatvirtintas.");scan|=f.Name.EndsWith("clamscan.exe",StringComparison.OrdinalIgnoreCase);fresh|=f.Name.EndsWith("freshclam.exe",StringComparison.OrdinalIgnoreCase);}if(!scan||!fresh)throw new IOException("Trūksta variklio failų.");}
  void Work(){Timer heartbeat=null;try{
    FolderMonitor.NoLinks(DataRoot);core=new Core(DataRoot);core.ExternalCancellation=()=>stopping.WaitOne(0);core.EngineBinaryDirectory=Path.Combine(ProgramRoot,"engine","clamav-1.4.6.win.x64");core.EngineDatabaseDirectory=Path.Combine(BaseRoot,"Databases");core.BundledHashPath=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"initial.hdb");
