    VerifyEngine();engineReady=true;manualControlReady=ServiceControlSecurity.Verify();var cfg=Data.Read<ServiceSettings>(Path.Combine(ProgramRoot,"service-config.json"),32768);if(cfg==null||cfg.PeriodHours<6||cfg.PeriodHours>168||cfg.StepDelaySeconds<1||cfg.StepDelaySeconds>30)throw new IOException("Paslaugos nuostatos nepatvirtintos.");
    core.Config.AutoDbUpdate=cfg.AutomaticUpdates;core.Config.AutoDetectionControl=cfg.DetectionControl;core.SaveSettings();
    string planFile=Path.Combine(DataRoot,"service-plan.json");plan=new DirectoryScanPlan(planFile,cfg.Roots,new[]{BaseRoot,ProgramRoot});realtime=new RealtimeChangeMonitor(cfg.Roots,new[]{BaseRoot,ProgramRoot},true,512,4);SaveReport("realtime",realtime.Summary+"\r\nŠaknys: "+string.Join(", ",realtime.Roots)+". Praradus įvykius paslauga tai žymi kaip aprėpties spragą; periodinė patikra veikia atskirai.");
    cache=new CleanDirectoryCache(Path.Combine(DataRoot,"clean-cache.json"));var gate=new LoadGate();var load=new SystemLoad();bool realtimeTurn=true;long lastBulkChangeReportAt=0;
    while(!stopping.WaitOne(0)){
     if(realtime!=null&&realtime.BulkChangeAlertAt>lastBulkChangeReportAt){lastBulkChangeReportAt=realtime.BulkChangeAlertAt;SaveReport("bulk-change","AUDITO SIGNALAS: per 15 s pakeista bent 100 skirtingų stebimų failų. Tai nėra viruso aptikimas; proceso tapatybė nenustatyta, failai neblokuojami ir netrinami. Patikrinkite tuo metu veikusias programas bei įvykių istoriją.\r\nSignalų skaičius: "+realtime.BulkChangeBursts+"; skirtingų kelių aktyviame lange: "+realtime.BulkChangeDistinctPaths+"; laikas: "+new DateTime(realtime.BulkChangeAlertAt,DateTimeKind.Utc).ToLocalTime().ToString("g"));}
     if(Interlocked.Exchange(ref scanRequested,0)==1&&PcScanPolicy.NewCycle(plan.State.Pending.Count,plan.State.Finished)){Data.Atomic(Path.Combine(DataRoot,"last-completed-plan.json"),Data.Json().Serialize(plan.State));File.Delete(planFile);plan=new DirectoryScanPlan(planFile,cfg.Roots,new[]{BaseRoot,ProgramRoot});}
     var manual=manualUpdates.Snapshot();if(manual.Pending){string wait=UpdateRequestPolicy.Hold(manual,load.OnAc());if(wait.Length>0){state=wait;Publish();if(stopping.WaitOne(10000))break;continue;}if(manualUpdates.Take()){core.Reset();databaseReady=false;databaseProbeAt=0;state="MANUAL_UPDATING_DATABASE";Publish();bool success=false;try{string result=core.ScheduledLocalEngineUpdate();SaveReport("update",result);EngineSafety.ValidateDatabaseFiles(core.EngineDatabase);success=core.Config.AutoDbSuccessAt>0&&core.NotChecked==0;if(success){databaseProbeAt=DateTime.UtcNow.Ticks;databaseReady=true;}}catch(OperationCanceledException){throw;}catch(Exception e) when(e is IOException||e is UnauthorizedAccessException){databaseReady=false;databaseProbeAt=0;SaveReport("update",Data.Clean(e.Message)+"\r\n"+Data.Diagnostic(e));}finally{generation=null;manualUpdates.Complete(success,DateTime.UtcNow.Ticks);state=success?"MANUAL_UPDATE_COMPLETED":"MANUAL_UPDATE_INCOMPLETE";Publish();}continue;}}
     string hold=gate.Evaluate(cfg.PauseOnBattery,load.OnAc(),cfg.PauseWhenBusy,load.Cpu());if(hold.Length>0){state=hold;Publish();if(stopping.WaitOne(10000))break;continue;}
     if(cfg.AutomaticUpdates&&AutonomyPolicy.UpdateDue(core.Config,DateTime.UtcNow.Ticks)){core.Reset();databaseReady=false;databaseProbeAt=0;state="UPDATING_DATABASE";Publish();string result=core.ScheduledLocalEngineUpdate();SaveReport("update",result);generation=null;if(core.Config.AutoDbSuccessAt>0&&core.NotChecked==0){databaseProbeAt=DateTime.UtcNow.Ticks;databaseReady=true;}}
    try{EngineSafety.ValidateDatabaseFiles(core.EngineDatabase);if(databaseProbeAt<=0||DateTime.UtcNow.Ticks-databaseProbeAt>=TimeSpan.FromHours(24).Ticks){databaseReady=false;state="CHECKING_ENGINE_DATABASE_READINESS";Publish();core.Reset();string probe=core.TestLocalEngineReadiness();SaveReport("readiness",probe);databaseProbeAt=DateTime.UtcNow.Ticks;}databaseReady=true;}catch(OperationCanceledException){throw;}catch(Exception e) when(e is IOException||e is UnauthorizedAccessException||e is ArgumentException||e is InvalidOperationException||e is System.TimeoutException||e is System.ComponentModel.Win32Exception){databaseReady=false;databaseProbeAt=0;state="ENGINE_READINESS_UNCONFIRMED_WAITING_UPDATE";SaveReport("readiness",Data.Clean(e.Message)+"\r\n"+Data.Diagnostic(e));Publish();if(stopping.WaitOne(30000))break;continue;}
     if(cfg.UseCleanCache&&generation==null)generation=CleanDirectoryCache.Generation(core.EngineDatabase,Path.Combine(ProgramRoot,"engine-integrity.json"),core.Check);
     string changedFile=realtimeTurn&&realtime!=null?realtime.Take(DateTime.UtcNow.Ticks):null;if(changedFile!=null){realtimeTurn=plan.State.Pending.Count==0;state="SCANNING_CHANGED_FILE";Publish();CheckChangedFile(changedFile);Publish();if(stopping.WaitOne(cfg.StepDelaySeconds*1000))break;continue;}
     if(plan.State.Pending.Count>0){core.Reset();state="SCANNING_DIRECTORY";Publish();
