       if(cache.Hit(directory,cacheGeneration,before,DateTime.UtcNow.Ticks)){Interlocked.Increment(ref cacheHits);SaveReport("scan","REUSED_PREVIOUS_RESULT: turinio SHA256 ir variklio/bazių karta sutampa. Nauja ClamAV patikra neatlikta. "+Data.Clean(directory));return false;}
