       if(before!=null&&core.EngineFindings==0&&core.HashFindings==0&&core.TestFindings==0&&core.NotChecked==0){string after=CleanDirectoryCache.Fingerprint(directory,core.Check);cache.Commit(directory,cacheGeneration,before,after,true,DateTime.UtcNow.Ticks);}SaveReport("scan",report);if(core.EngineFindings>0||core.HashFindings>0){try{SaveCase(directory,report);}catch(IOException e){throw new InvalidOperationException("Radinio išsaugoti nepavyko; planas nepaslenkamas.",e);}}return core.EngineFindings>0||core.HashFindings>0;}},core.Check,()=>core.NotChecked>0,()=>lastScanDetail);
      realtimeTurn=true;state=plan.State.Findings>0?"FINDINGS_REQUIRE_REVIEW":plan.State.Unverified>0?"COVERAGE_INCOMPLETE":"SCAN_IN_PROGRESS";Publish();if(stopping.WaitOne(cfg.StepDelaySeconds*1000))break;
     }else{
      realtimeTurn=true;state=plan.State.Findings>0?"FINDINGS_REQUIRE_REVIEW":plan.State.Unverified>0?"CYCLE_COMPLETE_WITH_GAPS":"CYCLE_FINISHED_NO_SIGNATURES";Publish();
      long now=DateTime.UtcNow.Ticks;
