      if(stopping.WaitOne(realtime!=null&&realtime.Ready?2000:30000))break;
     }
    }
    state="STOPPED";
   }catch(Exception e){failure=e;state=stopping.WaitOne(0)?"STOPPED_INCOMPLETE":"ERROR_PROTECTION_UNCONFIRMED";try{SaveReport("error",Data.Diagnostic(e));}catch{}}
  finally{if(heartbeat!=null)heartbeat.Dispose();if(realtime!=null)realtime.Dispose();try{Publish();}catch{}if(failure!=null&&!stopRequested){ExitCode=1;Environment.Exit(1);}}
  }
  void CheckChangedFile(string path){core.Reset();try{FolderMonitor.NoLinks(path);if(!File.Exists(path)||Directory.Exists(path)){realtime.MarkUnverified();SaveReport("realtime-gap","Failo pokyčio nepavyko patikrinti, nes failas iki patikros dingo arba tapo aplanku: "+Data.Clean(path));return;}Witness changed=core.Scan(path,268435456L,true);string report=core.ScanLocalEngine(changed);if(core.NotChecked==0)realtime.MarkScanned();else realtime.MarkUnverified();SaveReport(core.NotChecked==0?"realtime":"realtime-gap",report);if(core.EngineFindings>0||core.HashFindings>0)SaveCase(Path.GetDirectoryName(path),report);}catch(OperationCanceledException){throw;}catch(Exception e) when(e is IOException||e is UnauthorizedAccessException||e is ArgumentException||e is InvalidOperationException||e is System.TimeoutException||e is System.ComponentModel.Win32Exception){realtime.MarkUnverified();SaveReport("realtime-gap","Failo pokyčio patikra nepatvirtinta: "+Data.Clean(path)+"\r\n"+Data.Diagnostic(e));}}
  void SaveReport(string kind,string report){Data.Atomic(Path.Combine(DataRoot,"last-"+kind+".txt"),Data.CleanLog(report));}
  void SaveCase(string directory,string report){string cases=Path.Combine(DataRoot,"cases");Directory.CreateDirectory(cases);if(Directory.EnumerateFiles(cases,"*.json").Take(501).Count()>=500)throw new IOException("Radinių žurnalas pilnas. Ankstesni įrašai išsaugoti.");var record=new CaseRecord{Id=Guid.NewGuid().ToString("N"),At=DateTime.UtcNow.Ticks,Directory=directory,Report=Data.CleanLog(report)};Data.Atomic(Path.Combine(cases,record.Id+".json"),Data.Json().Serialize(record));}
  
